WITH enriched AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, NTILE(5) OVER (PARTITION BY txn_type ORDER BY amount, id) amount_bucket, LAST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_merchant FROM transactions) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.last_known_merchant, (SELECT MAX(x.amount) FROM transactions x WHERE x.account_id = s.account_id) AS max_transaction_amount FROM enriched s ORDER BY txn_type DESC NULLS FIRST, txn_time DESC;
